sys_script_include.script:
var gerateOTP = Class.create();
gerateOTP.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    generateOTP: function() {

		var generatedOTP =   Math.floor(100000 + Math.random() * 900000).toString();
		return  generatedOTP.substring(0,7);
    },

    setOTP: function(userRec) {

        var getOTP = this.generateOTP();
		gs.addInfoMessage('Generated OTP ' + getOTP);
		var getUserRec = this.getParameter('sysparm_userRec');
        var getUserData = new GlideRecord('sys_user');
        getUserData.get(getUserRec);
        getUserData.correlation_id = getOTP;
        getUserData.update();

		if(getUserData.correlation_id != ''){
			return 'OTP Generated';
		}

    },



    type: 'gerateOTP'
});
